M.by_id = {}
for name, entry in pairs(M.by_name) do
    entry.name = name
    M.by_id[entry.id] = entry
end

function M.get(ws)
    if type(ws) == "number" then
        return M.by_id[ws]
    end
    if type(ws) == "string" then
        return M.by_name[ws]
    end
    return nil
end

function M.score(ws)
    local entry = M.get(ws)
    return entry and entry.progression_score or 0
end

return M
